),
prod_funcoes AS MATERIALIZED (
  SELECT DISTINCT p.proname AS funcao
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public'
),
prod_gatilhos AS MATERIALIZED (
  SELECT c.relname AS tabela,
         md5(string_agg(t.tgname, ',' ORDER BY t.tgname)) AS impressao,
         string_agg(t.tgname, ', ' ORDER BY t.tgname) AS lista
  FROM pg_trigger t
  JOIN pg_class c ON c.oid = t.tgrelid
  JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public'
  WHERE NOT t.tgisinternal
  GROUP BY c.relname
),
prod_politicas AS MATERIALIZED (
  SELECT tablename AS tabela,
         md5(string_agg(policyname, ',' ORDER BY policyname)) AS impressao,
         string_agg(policyname, ', ' ORDER BY policyname) AS lista
  FROM pg_policies WHERE schemaname = 'public'
  GROUP BY tablename
)

SELECT 'função' AS tipo, r.funcao AS objeto, 'só no repositório' AS situacao,
       'falta aplicar na produção — rotina que a chamar vai quebrar em execução' AS detalhe
FROM repo_funcoes r
WHERE NOT EXISTS (SELECT 1 FROM prod_funcoes p WHERE p.funcao = r.funcao)

UNION ALL
SELECT 'função', p.funcao, 'só na produção',
       'criada fora das migrations; trazer para o repositório'
FROM prod_funcoes p
WHERE NOT EXISTS (SELECT 1 FROM repo_funcoes r WHERE r.funcao = p.funcao)

UNION ALL
SELECT 'gatilhos', r.tabela, 'difere', 'produção tem: ' || left(p.lista, 300)
FROM repo_gatilhos r JOIN prod_gatilhos p ON p.tabela = r.tabela
WHERE p.impressao <> r.impressao

UNION ALL
SELECT 'gatilhos', r.tabela, 'só no repositório', 'tabela sem nenhum gatilho na produção'
FROM repo_gatilhos r
WHERE NOT EXISTS (SELECT 1 FROM prod_gatilhos p WHERE p.tabela = r.tabela)

UNION ALL
SELECT 'políticas', r.tabela, 'difere', 'produção tem: ' || left(p.lista, 300)
FROM repo_politicas r JOIN prod_politicas p ON p.tabela = r.tabela
WHERE p.impressao <> r.impressao

UNION ALL
SELECT 'políticas', r.tabela, 'só no repositório', 'tabela sem nenhuma política na produção'
FROM repo_politicas r
WHERE NOT EXISTS (SELECT 1 FROM prod_politicas p WHERE p.tabela = r.tabela)

UNION ALL
SELECT 'RESUMO', 'rotinas e regras', 'referência',
       (SELECT count(*)::text FROM prod_funcoes) || ' funções na produção · '
    || (SELECT count(*)::text FROM repo_funcoes) || ' esperadas pelo repositório'

ORDER BY 1, 3, 2;
